function homeNamedStaffEntries(){
 ensureHomeBase();const h=state.world.homeBase;return[
  {role:'steward',title:'Steward',obj:h.staff.steward,owner:h.staff,slot:'steward'},
  {role:'logistics',title:'Logistics Master',obj:h.logistics.master,owner:h.logistics,slot:'master'},
  {role:'headguard',title:'Head Guard',obj:h.security.headGuard,owner:h.security,slot:'headGuard'},
  {role:'economic',title:'Economic Adviser',obj:h.business.adviser,owner:h.business,slot:'adviser'},
  {role:'artisan',title:'Master Artisan',obj:h.artisan?.master,owner:h.artisan,slot:'master'}
 ].filter(x=>x.obj)
}
function homeNamedStaffBaseCandidate(role,obj){
 const pools={steward:HOME_STEWARD_CANDIDATES,logistics:LOGISTICS_MASTER_CANDIDATES,headguard:HEAD_GUARD_CANDIDATES,economic:ECONOMIC_ADVISER_CANDIDATES,artisan:(typeof MASTER_ARTISAN_CANDIDATES!=='undefined'?MASTER_ARTISAN_CANDIDATES:[])},pool=pools[role]||[];
 return pool.find(x=>x.id===obj.id||x.id===obj.candidateId||x.name===obj.name)||null
}
function homeEnsureNamedStaffCareer(obj,role){
 if(!obj)return null;const base=homeNamedStaffBaseCandidate(role,obj),expected=base?.salary||Math.max(60,Math.round((obj.salary||24)*3));
 if(!obj.salaryScaleV2){obj.salary=Math.max(obj.salary||0,expected);obj.salaryScaleV2=true}
 obj.competence=clamp(Math.round(obj.competence||base?.competence||2),1,10);if(obj.startingCompetence==null)obj.startingCompetence=Math.min(5,obj.competence);
 if(obj.performance==null)obj.performance=50;if(obj.lastCareerReviewDay==null)obj.lastCareerReviewDay=obj.hiredDay||state.world.day;if(obj.raiseRequests==null)obj.raiseRequests=0;if(obj.deniedRaises==null)obj.deniedRaises=0;if(obj.commendations==null)obj.commendations=0;if(obj.lastRewardDay==null)obj.lastRewardDay=-99;return obj
}
function homeNamedStaffPerformanceDelta(role){
 const h=state.world.homeBase;if(role==='steward'){const c=homeStaffCoverage();return c>=110?3:c>=90?1:c<70?-3:0}
 if(role==='logistics'){const avg=homeSupplyAverage();return avg>=70?3:avg>=45?1:avg<25?-3:0}
 if(role==='headguard'){const S=h.security;return S.pending?-3:S.readiness>=75?2:S.readiness<40?-2:1}
 if(role==='economic'){return (h.business.lastIncome||0)>=35?3:(h.business.lastIncome||0)>=18?1:-1}
 if(role==='artisan'){const A=h.artisan;return !A?.master?0:(A.workmen||0)>=5?3:(A.workmen||0)>=2?1:-1}
 return 0
}
function homeNamedStaffDailyTick(){
 if(!isOpenWorld())return;ensureHomeBase();const T=state.world.homeBase.staff;if(T.namedStaffMatter)return;
 for(const e of homeNamedStaffEntries()){const s=homeEnsureNamedStaffCareer(e.obj,e.role);s.performance=clamp((s.performance||50)+homeNamedStaffPerformanceDelta(e.role)+rnd(-1,1),0,100);
  if(state.world.day-(s.lastCareerReviewDay||state.world.day)<14)continue;s.lastCareerReviewDay=state.world.day;
  const strong=s.performance>=62,weak=s.performance<=28;
  if(s.competence<10&&strong&&chance(.32+Math.min(.18,(s.performance-62)/160))){s.competence++;s.performance=clamp(s.performance-8,0,100);homeStaffReport(SOSText("hall_staff_correspondence.homeNamedStaffDailyTick.001",s.name,e.title,s.competence),'good');recordWorldHistory(SOSText("hall_staff_correspondence.homeNamedStaffDailyTick.002",s.name,s.competence),'good','home');
   const fair=Math.round((homeNamedStaffBaseCandidate(e.role,s)?.salary||s.salary)*(1+Math.max(0,s.competence-(s.startingCompetence||3))*.08));
   if(s.competence>=6&&s.salary<fair&&chance(.45)){T.namedStaffMatter={id:'staffraise_'+uid(),kind:'raise',role:e.role,title:e.title,staffName:s.name,requestedSalary:Math.max(s.salary+6,fair),day:state.world.day};s.raiseRequests++}
  }else if(s.competence>1&&weak&&chance(.08)){s.competence--;s.performance=clamp(s.performance+8,0,100);homeStaffReport(SOSText("hall_staff_correspondence.homeNamedStaffDailyTick.003",s.name,e.title,s.competence),'bad');recordWorldHistory(SOSText("hall_staff_correspondence.homeNamedStaffDailyTick.004",s.name,s.competence),'bad','home')}
 }
}
function homeNamedStaffByRole(role){return homeNamedStaffEntries().find(x=>x.role===role)||null}
function homeResolveNamedStaffRaise(accept){
 ensureHomeBase();const T=state.world.homeBase.staff,m=T.namedStaffMatter;if(!m||m.kind!=='raise')return showHomeStaff();const e=homeNamedStaffByRole(m.role),s=e?.obj;if(!s){T.namedStaffMatter=null;return showHomeStaff()}
 if(accept){s.salary=m.requestedSalary;s.deniedRaises=0;s.performance=clamp((s.performance||50)+8,0,100);T.morale=clamp(T.morale+3,0,100);homeStaffReport(SOSText("hall_staff_correspondence.homeResolveNamedStaffRaise.001",s.name,s.salary),'good')}
 else{s.deniedRaises=(s.deniedRaises||0)+1;s.performance=clamp((s.performance||50)-10,0,100);const leaveChance=clamp(.12+s.deniedRaises*.12+(s.competence>=8?.08:0)+(T.morale<55?.1:0),.12,.55);if(chance(leaveChance)){e.owner[e.slot]=null;homeStaffReport(SOSText("hall_staff_correspondence.homeResolveNamedStaffRaise.002",s.name),'bad');recordWorldHistory(SOSText("hall_staff_correspondence.homeResolveNamedStaffRaise.003",s.name),'bad','home')}else homeStaffReport(SOSText("hall_staff_correspondence.homeResolveNamedStaffRaise.004",s.name),'bad')}
 T.namedStaffMatter=null;save();showHomeStaff()
}
function homeRewardNamedStaff(role,kind){
 ensureHomeBase();const T=state.world.homeBase.staff,e=homeNamedStaffByRole(role),s=e?.obj;if(!s)return showHomeStaff();homeEnsureNamedStaffCareer(s,role);
 if(kind==='raise'){const bump=Math.max(6,Math.round(s.salary*.10));s.salary+=bump;s.performance=clamp(s.performance+6,0,100);T.morale=clamp(T.morale+1,0,100);homeStaffReport(SOSText("hall_staff_correspondence.homeRewardNamedStaff.001",s.name,bump,s.salary),'good')}
 if(kind==='commend'){if(state.world.day-(T.lastHallCommendationDay||-99)<30)return actionResult(SOSText("hall_staff_correspondence.homeRewardNamedStaff.002"),SOSText("hall_staff_correspondence.homeRewardNamedStaff.003"),'info',showHomeStaff);T.lastHallCommendationDay=state.world.day;s.commendations=(s.commendations||0)+1;s.lastRewardDay=state.world.day;s.performance=clamp(s.performance+12,0,100);T.morale=clamp(T.morale+6,0,100);homeStaffReport(SOSText("hall_staff_correspondence.homeRewardNamedStaff.004",s.name,e.title),'good');recordWorldHistory(SOSText("hall_staff_correspondence.homeRewardNamedStaff.005",s.name,e.title),'good','home')}
 save();showHomeStaff()
}
function homeNamedStaffCardsHTML(){
 return homeNamedStaffEntries().map(e=>{const s=homeEnsureNamedStaffCareer(e.obj,e.role),grade=s.performance>=80?'Excellent':s.performance>=60?'Strong':s.performance>=40?'Steady':s.performance>=25?'Struggling':'Poor';return `<div class="card named-staff-career"><h3>${esc(s.name)} — ${esc(e.title)}</h3><div class="stat-row"><span>Competence</span><b>${s.competence}/10</b></div><div class="stat-row"><span>Recent performance</span><b>${grade}</b></div><div class="stat-row"><span>Salary</span><b>${s.salary} gold / 14 days</b></div><div class="choice-list compact"><button data-staffreward="${e.role}:raise">Give Salary Increase</button><button data-staffreward="${e.role}:commend" ${state.world.day-(state.world.homeBase.staff.lastHallCommendationDay||-99)<30?'disabled':''}>Hall-Wide Commendation</button></div></div>`}).join('')
}
function homeStaffReport(text,tone='info'){ensureHomeBase();const T=state.world.homeBase.staff;T.reports.push({day:state.world.day,text,tone});T.reports=T.reports.slice(-30)}
function homeStaffTotal(){ensureHomeBase();const h=state.world.homeBase,T=h.staff,A=h.artisan||{};return (T.cooks||0)+(T.attendants||0)+(T.messengers||0)+(T.medical||0)+(T.steward?1:0)+(A.master?1:0)+(A.workmen||0)}
function homeStaffPayroll(){ensureHomeBase();const T=state.world.homeBase.staff;let pay=(T.steward?.salary||0);for(const [id,d] of Object.entries(HOME_STAFF_ROLES))pay+=(T[id]||0)*d.wage;return pay}
function homeStaffDemand(){ensureHomeBase();const h=state.world.homeBase,H=h.hospitality;let demand=6+Math.ceil((h.security.guards||4)/4)+Math.ceil(partyMembers(false).length/3);if(H.guest)demand+=Math.ceil(homeGuestSize(H.guest)/2);demand+=homeGatheringArrived().reduce((n,x)=>n+Math.ceil((x.size||1)/3),0);if(h.upgrades.banquetFacilities)demand+=1;if(hallPrisonerCount()>0)demand+=1;return demand}
function homeStaffBaseCapacity(){ensureHomeBase();const T=state.world.homeBase.staff,stew=T.steward?1+(T.steward.competence||2)*.12:.9;return Math.round(((T.cooks||0)*1.5+(T.attendants||0)*1.35+(T.messengers||0)*.75+(T.medical||0)*.8)*stew)}
function homeStaffCapacity(){ensureHomeBase();const h=state.world.homeBase,diverted=h.logistics?.lastEmergencyLocalDay===state.world.day?(h.logistics.emergencyStaffAssigned||0):0;return Math.max(0,Math.round(homeStaffBaseCapacity()-diverted*1.2))}
function homeStaffCoverage(){const d=Math.max(1,homeStaffDemand());return Math.round(homeStaffCapacity()/d*100)}
